from pathlib import Path

SW = Path(__file__).resolve().parents[1]
path = SW / 'index.html'
text = path.read_text()

text = text.replace('styles.css?v=films-20260907', 'styles.css?v=landing-20260907')
text = text.replace('app.js?v=films-20260907', 'app.js?v=landing-20260907')
text = text.replace('Star-Wars-Histomap-Poster.png?v=films-20260907', 'Star-Wars-Histomap-Poster.png?v=landing-20260907')

needle = '    <section class="atlas" aria-label="Interactive galactic timeline">\n      <div class="atlas-controls">'
intro = '''    <section class="atlas" aria-label="Interactive galactic timeline">\n      <section id="launch-intro" class="launch-intro" aria-labelledby="launch-title">\n        <div class="launch-intro-bg" aria-hidden="true"></div>\n        <div class="launch-card">\n          <button id="launch-close" class="launch-close" aria-label="Skip introduction">×</button>\n          <span class="launch-eyebrow">UNOFFICIAL FAN ATLAS · STORY SPOILERS</span>\n          <div class="launch-lockup"><img src="title-art/main.webp" alt="Star Wars" width="586" height="254"><span>HISTOMAP</span></div>\n          <h2 id="launch-title">The history of the Star Wars galaxy, all at once.</h2>\n          <p class="launch-deck">Follow powers as they rise, fracture, transform, and fall — with films and television, character lifelines, and separate Legends histories locked to the same chronology.</p>\n          <div class="launch-features" aria-label="Atlas contents"><span>Canon · 500 BBY—35 ABY</span><span>Films &amp; TV</span><span>Character lifelines</span><span>Legends kept separate</span></div>\n          <div class="launch-actions"><button id="launch-explore" class="launch-primary">Explore interactive map <span aria-hidden="true">↓</span></button><a class="launch-secondary" href="downloads/Star-Wars-Histomap-Poster.png?v=landing-20260907" download="Star-Wars-Histomap-Poster.png">View / download full poster</a></div>\n          <div class="launch-foot"><span>Scroll downward through time · select any stream or event</span><span>By J. Hunter Sizemore · histomaps.org</span></div>\n        </div>\n      </section>\n      <div class="atlas-controls">'''
if needle not in text:
    raise RuntimeError('atlas insertion point not found')
text = text.replace(needle, intro, 1)

style = r'''\n  <style id="launch-experience-styles">\n    .atlas{position:relative}\n    .launch-intro{position:absolute;inset:0 0 26px;z-index:24;display:grid;place-items:center;overflow:auto;padding:clamp(18px,4vw,52px);background:#020507e8;isolation:isolate}\n    .launch-intro[hidden]{display:none}\n    .launch-intro-bg{position:absolute;inset:0;z-index:-2;background-image:linear-gradient(180deg,#0008,#061117d9 45%,#000e),url('assets/starfield.webp');background-size:cover,cover;background-position:center;filter:saturate(.75)}\n    .launch-intro:after{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(circle at 50% 38%,transparent 0 18%,#0007 58%,#000c 100%);pointer-events:none}\n    .launch-card{position:relative;width:min(900px,100%);padding:clamp(28px,5vw,58px);border:1px solid #745f35;background:linear-gradient(145deg,#0b1419e8,#071014f2);box-shadow:0 30px 100px #000d,0 0 80px #d6af4a10}\n    .launch-close{position:absolute;right:14px;top:10px;width:40px;height:40px;font-size:28px;color:#9eb0b0}\n    .launch-eyebrow{display:block;margin-bottom:20px;font-size:12px;letter-spacing:1.8px;color:#b8c3c2}\n    .launch-lockup{display:flex;align-items:center;gap:18px;color:var(--gold);font:400 clamp(26px,4.4vw,48px)/1 'Star Jedi','Pathway Gothic One',sans-serif;letter-spacing:3px}\n    .launch-lockup img{display:block;width:clamp(125px,21vw,210px);height:auto;max-height:90px;object-fit:contain}\n    .launch-card h2{max-width:820px;margin:28px 0 16px;font:400 clamp(38px,6.1vw,72px)/.98 'Pathway Gothic One',Impact,sans-serif;letter-spacing:-.7px;color:#f2eee2;text-wrap:balance}\n    .launch-deck{max-width:760px;margin:0;color:#c7d2d0;font-size:clamp(16px,2vw,20px);line-height:1.55}\n    .launch-features{display:flex;flex-wrap:wrap;gap:8px;margin:26px 0 30px}\n    .launch-features span{padding:7px 10px;border:1px solid #405155;background:#0d1c21cc;color:#bdc9c8;font-size:12px;letter-spacing:.35px}\n    .launch-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n    .launch-primary,.launch-secondary{min-height:46px;padding:11px 18px;border-radius:3px;font-weight:600;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:10px}\n    .launch-primary{background:var(--gold);color:#101619}.launch-primary:hover{color:#000;background:#efd497}\n    .launch-secondary{border:1px solid #7b6742;color:#efd493;background:#0b1215cc}.launch-secondary:hover{border-color:#d8b76d;color:#fff}\n    .launch-foot{display:flex;justify-content:space-between;gap:20px;margin-top:34px;padding-top:16px;border-top:1px solid #334246;color:#8fa0a0;font-size:12px}\n    @media(max-width:700px){.launch-intro{align-items:start;padding:12px}.launch-card{padding:28px 22px 22px;margin:auto 0}.launch-card h2{font-size:44px;margin-top:22px}.launch-lockup{gap:12px}.launch-lockup img{width:132px}.launch-lockup span{font-size:26px}.launch-features{margin:20px 0}.launch-actions{display:grid}.launch-primary,.launch-secondary{width:100%}.launch-foot{display:grid;gap:5px;margin-top:22px}.launch-deck{font-size:16px}}\n    @media(max-height:700px) and (orientation:landscape){.launch-intro{padding:10px}.launch-card{padding:22px 28px}.launch-card h2{font-size:42px;margin:14px 0 10px}.launch-deck{font-size:15px}.launch-features{margin:14px 0}.launch-foot{margin-top:14px}.launch-lockup img{width:120px;max-height:52px}.launch-lockup span{font-size:27px}.launch-eyebrow{margin-bottom:10px}}\n    @media(prefers-reduced-motion:no-preference){.launch-card{animation:launch-rise .38s ease-out both}@keyframes launch-rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}}\n  </style>'''
head_end = '</head>'
if head_end not in text:
    raise RuntimeError('head close not found')
text = text.replace(head_end, style + '\n' + head_end, 1)

script = r'''\n  <script id="launch-experience-script">\n    (()=>{\n      const intro=document.getElementById('launch-intro');\n      if(!intro)return;\n      let seen=false;try{seen=sessionStorage.getItem('starwars-histomap-intro-v1')==='1'}catch(e){}\n      if(seen){intro.hidden=true;return}\n      const dismiss=()=>{intro.hidden=true;try{sessionStorage.setItem('starwars-histomap-intro-v1','1')}catch(e){}requestAnimationFrame(()=>document.getElementById('map-scroll')?.focus({preventScroll:true}))};\n      document.getElementById('launch-explore')?.addEventListener('click',dismiss);\n      document.getElementById('launch-close')?.addEventListener('click',dismiss);\n    })();\n  </script>'''
body_end = '</body>'
if body_end not in text:
    raise RuntimeError('body close not found')
text = text.replace(body_end, script + '\n' + body_end, 1)

path.write_text(text)
print('Added first-load Star Wars Histomap landing experience.')
